const BUBBLE_ICONS={none:'无',heart:'爱心',star:'星芒',bow:'蝴蝶结',flower:'花瓣',moon:'月光'};
function bubbleCfg(c){return c&&c.bubbleStyle||(S.me&&S.me.wxFeatures&&S.me.wxFeatures.globalBubble)||null;}
