function groupBubbleBase(sid,b){const me=sid==='me';return Object.assign({bg:me?'#95ec69':'#2c2c2e',text:me?'#0b3b18':'#ececec',shape:'square',avatar:'original',icon:'none',iconColor:'#e777a5',glow:false},b||{});}
